type Handler = Arc<dyn Fn(&Event) + Send + Sync>;
#[derive(Clone, Default)]
pub struct Subject(Arc<RwLock<Vec<(u64, Handler)>>>);
impl Subject {
    pub fn subscribe(&self, h: Handler) -> u64 {
        let mut s = self.0.write().unwrap(); let id = s.len() as u64; s.push((id, h)); id
    }
    pub fn notify(&self, e: &Event) {
        let hs: Vec<Handler> = self.0.read().unwrap().iter().map(|(_, h)| Arc::clone(h)).collect();
        for h in hs { h(e); }   // read lock already released
    }
}

